update_rule.pseudocode:
if t == 0:
  if network_type == 'Empirical' or use_empirical_network:
    load network from data_sources.network_edges
  else if network_type == 'WS':
    generate Watts-Strogatz with N=population_size, K=avg_degree, p=ws_rewiring_prob_initial
  else if network_type == 'ER':
    generate Erdos-Renyi with N=population_size, p=avg_degree/(N-1)
  else if network_type == 'BA':
    generate Barabasi-Albert with N=population_size, m=avg_degree/2
  assign edge weights ~ Normal(edge_weight_mean, edge_weight_sd), clipped to [0.05, 10]
  adjust clustering using clustering_bias via triadic-closure rewiring during initialization
  output signal.network, signal.edge_weights
else:
  with probability dynamic_rewiring_rate_daily per node:
    perform degree-preserving rewiring favoring assortativity_homophily on age, income (Jaccard similarity)
  output updated signal.network, signal.edge_weights

policy_incentive = 0
if day >= incentive_start_day:
  policy_incentive = incentive_strength
policy_mandate = 0
if day >= mandate_start_day:
  policy_mandate = penalty_strength
policy_message_boost = 0
if day >= messaging_campaign_start_day:
  policy_message_boost = messaging_intensity
emit signal.policy_incentive, signal.policy_mandate, signal.policy_message_boost, enforcement_probability

for each agent i:
  exposure_i *= exp(-ln(2)/exposure_decay_half_life_days)
for each info source s (1..num_info_sources):
  if Bernoulli(exogenous_message_rate_daily * (1 + signal.policy_message_boost)):
    choose broadcast targets proportional to degree
    delivered_cred = source_credibility_mean * (1 - misinfo_fraction if s is corrective else 1)
    for each target j:
      if Bernoulli(transmission_prob_edge * f(selectivity=info_selectivity_shape, polarization=content_polarization, match=agent_j_polarity)):
        exposure_j += delivered_cred
for each edge (i,j):
  if Bernoulli(transmission_prob_edge * edge_weight(i,j)):
    exposure_j += min(awareness_i, 1.0) * 0.5
    exposure_i += min(awareness_j, 1.0) * 0.5
apply correction_effectiveness to reduce misinformation contribution in exposure scores
emit signal.exposure_scores

for each node i with probability rewiring_rate_daily:
  select neighbor j where adopted_i != adopted_j with probability proportional to (1 - homophily_on_adoption)
  if such j exists:
    remove edge (i,j)
    with probability triadic_closure_prob:
      pick k from neighbors of i's neighbors that is not connected to i and adopted_k == adopted_i (if possible)
    else:
      pick k uniformly from nodes not connected to i with adopted_k == adopted_i (if possible)
    if degree(i) < max_degree_cap and k exists:
      add edge (i,k) with weight drawn from Normal(edge_weight_mean, edge_weight_sd)
emit updated signal.network
